<template>
    <div style="height: 100%;width:100%;background-color:#1e2227">
        <div class="header">
            <div class="left">
                <ul>
                    <li @click="goto('/pc')" title="回到推荐页">
                        {{ $t('NAVBAR.recommend') }}</li>
                    <li style=" border-top: 3px solid #fc5531;" @click="goto('/picWarehouse')" title="你已经再图片仓库了">
                        {{ $t('NAVBAR.Gallery') }}</li>
                </ul>
            </div>
            <div class="center"></div>
            <div class="right">
                <Lang class="lang" title="点击切换语言"></Lang>
            </div>
        </div>
        <div class="picBody">
            <Waterfall :list="list" style="background-color: transparent;">
                <template #item="{ item, url, index }">
                    <div class="card">
                        <LazyImg class="card_img" :url="url" />
                    </div>
                </template>
            </Waterfall>
        </div>
    </div>
</template>

<script>
import axios from "axios";
import { LazyImg, Waterfall } from 'vue-waterfall-plugin'
import 'vue-waterfall-plugin/dist/style.css'
export default {
    data() {
        return {
            list: [
            ]
        };
    },
    components: { LazyImg, Waterfall }, // 组件列表
    created() {
        this.getHomelist()
    },
    mounted() { },
    methods: {
        goto(index) {
            if (this.$route.fullPath !== index) {
                this.$router.push(index);
            } else {
                console.log("目标位置与当前位置相同，跳过导航");
            }
        },
        getHomelist() {
            axios.get("/JSON/picWarehouse/20241015.json").then(res => {
                this.list = res.data.data.map(item => ({
                    src: item.url
                }));
                // this.list = res.data.data;
            });
        },
    }
};
</script>

<style lang="scss" scoped>
.header {
    position: sticky; //用于保持元素置顶
    top: 0; //用于保持元素置顶
    z-index: 1; //用于保持元素置顶
    width: 100%;
    min-width: 1280px;
    height: 48px;
    line-height: 48px;
    padding: 0 24px;
    margin: 0 auto;
    background: #292961;
    -webkit-box-sizing: border-box;
    box-sizing: border-box;
    display: -webkit-box;
    display: -ms-flexbox;
    display: flex;
    -webkit-box-pack: justify;
    -ms-flex-pack: justify;
    justify-content: space-between;
    box-shadow: 0 2px 6px rgba(100, 100, 100, .15);
    -webkit-user-select: none;
    /* Safari 无法选中改文本 */
    -moz-user-select: none;
    /* Firefox 无法选中改文本 */
    -ms-user-select: none;
    /* IE10+/Edge 无法选中改文本 */
    user-select: none;

    /* Standard syntax 无法选中改文本 */

    .left {
        ul {
            width: auto;
            margin: 0px;

        }

        li {
            position: relative;
            display: inline-block;
            list-style: none;
            font-size: 14px;
            height: 100%;
            padding: 0 10px;
            border-top: 3px solid #fc5531;
            font-weight: 600;
            margin: 0 5px 0 0;
            background-color: transparent;
            background-image: none;
            border-color: transparent;
            color: #1b69b6;
            box-shadow: none;
        }

        li:hover {
            cursor: pointer;
            /* 鼠标移动到上面显示小手 */
            background-color: #4090df !important;
            /* 添加 !important 以确保优先级 */
            color: rgb(250, 250, 250) !important;
            /* 添加 !important 以确保优先级 */
        }

    }

}

.picBody {
    width: 79%;
    min-width: 950px;

    margin: 0 auto;
    // padding: 30px;
    margin-top: 50px;
    margin-bottom: 50px;
    text-align: left;
    color: #000;
    line-height: 1.7;
    font-size: 14px;

    .card_img {
        border-radius: 5px;
    }
}

.grid-container {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-gap: 10px;
}

.grid-item {
    background-color: #f1f1f1;

    text-align: center;
}

.lang {
    color: #a8a8cd;
    padding-right: 40px;
}

.lang:hover {
    color: #d2d2fe;
    cursor: pointer;
}
</style>